/**
 * Widget claim verification.
 *
 * Widget HTML is generated by the same model that wrote the outline, and the
 * pipeline's only gate used to be "the HTML extracts and its inline JS parses".
 * That proves syntax, not truth: a simulation can parse perfectly and still
 * clamp away the very behaviour its own presets advertise.
 *
 * This module does two things, in that order:
 *
 * 1. Deterministically execute the widget in a stubbed `vm` sandbox and probe
 *    its declared variables/presets (`widget-sandbox.ts`). Mechanical findings
 *    (a throwing script, NaN, a dead slider, an inert preset) need no model.
 * 2. Optionally, hand a *blind* projection — the claims plus the observed
 *    behaviour table, never the source — to an independent verifier that can
 *    judge whether the behaviour matches the claims. Like quiz verification,
 *    every path is fail-open: no verdict means no signal.
 *
 * Nothing here mutates the generated HTML and nothing here executes code
 * outside the sandbox module's vm context.
 */

import { parseJsonResponse } from './json-repair.js';
import type { AICallFn } from './pipeline-types.js';
import type {
  WidgetPresetClaim,
  WidgetProbeResult,
  WidgetProbeSnapshot,
  WidgetVariableClaim,
} from './widget-sandbox.js';
import { probeWidgetHtml } from './widget-sandbox.js';

export type { WidgetPresetClaim, WidgetVariableClaim } from './widget-sandbox.js';

export interface WidgetVerificationIssue {
  /** Stable, short category. Unknown codes from a host verifier are preserved. */
  code: string;
  /** Learner-invisible, model-facing description of the contradiction. */
  message: string;
}

/** One probe row in the blind projection. No source code is included. */
export interface WidgetObservation {
  label: string;
  values: Record<string, number>;
  published: Record<string, unknown> | null;
  visibleText: Record<string, string>;
}

/**
 * Everything a verifier is allowed to see. The HTML source is deliberately
 * absent: a verifier that could read the generator's own answer would simply
 * agree with it, the same way a quiz verifier must not see the answer key.
 */
export interface WidgetVerificationContext {
  widgetType: string;
  title: string;
  description: string;
  keyPoints: readonly string[];
  claims: {
    variables: readonly WidgetVariableClaim[];
    presets: readonly WidgetPresetClaim[];
    /** Variables the OUTLINE promised, as opposed to what the widget declared. */
    expectedVariables: readonly string[];
    /** Concept the outline asked the widget to model. */
    expectedConcept?: string;
  };
  observations: readonly WidgetObservation[];
  scriptErrors: readonly string[];
}

/**
 * Blind verifier callback. A well-formed, non-empty issue list is fed back into
 * the bounded generation loop; null, undefined and throws mean "no signal".
 */
export type WidgetVerifier = (
  context: WidgetVerificationContext,
) => Promise<readonly WidgetVerificationIssue[] | null | undefined>;

const MAX_ISSUES = 5;
const MAX_MESSAGE_CHARS = 400;

/** Published state is nested (`{ summary, state: {...} }`), so flatten it. */
function flattenPrimitives(
  value: unknown,
  prefix: string,
  out: Array<[string, unknown]>,
  depth = 0,
): void {
  if (depth > 4 || out.length >= 200) return;
  if (value !== null && typeof value === 'object') {
    for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
      flattenPrimitives(child, prefix ? `${prefix}.${key}` : key, out, depth + 1);
    }
    return;
  }
  if (['number', 'string', 'boolean'].includes(typeof value)) out.push([prefix, value]);
}

function finiteNumbers(value: unknown): number[] {
  const flat: Array<[string, unknown]> = [];
  flattenPrimitives(value, '', flat);
  const numbers: number[] = [];
  for (const [, entry] of flat) {
    if (typeof entry === 'number') numbers.push(entry);
  }
  return numbers;
}

function observableSignature(snapshot: WidgetProbeSnapshot): string {
  // Include primitive published values, not just numbers: a control whose only
  // effect is a text summary is still observable, and must not be called dead.
  const flat: Array<[string, unknown]> = [];
  flattenPrimitives(snapshot.published, '', flat);
  const published = flat
    .map(([key, value]) => `${key}=${String(value)}`)
    .sort()
    .join(',');
  const text = Object.entries(snapshot.visibleText)
    .map(([id, value]) => `${id}=${value}`)
    .sort()
    .join('|');
  return `${published}::${text}`;
}

function wordTokens(value: string): string[] {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .filter((token) => token.length >= 3);
}

/** Outline wording and generated control names rarely match exactly. */
function outlineVariableCovered(expected: string, generated: readonly WidgetVariableClaim[]) {
  const expectedTokens = wordTokens(expected);
  if (expectedTokens.length === 0) return true;
  return generated.some((variable) => {
    const genTokens = wordTokens(variable.name);
    return expectedTokens.some((token) =>
      genTokens.some(
        (candidate) =>
          candidate === token || candidate.startsWith(token) || token.startsWith(candidate),
      ),
    );
  });
}

/**
 * Mechanical checks that need no domain knowledge and no model call. These
 * run for every widget before any verifier is consulted.
 */
export function deterministicWidgetIssues(
  result: WidgetProbeResult,
  claims: WidgetVerificationContext['claims'],
): WidgetVerificationIssue[] {
  const issues: WidgetVerificationIssue[] = [];

  for (const error of result.errors.slice(0, 3)) {
    issues.push({ code: 'script-error', message: `Widget script failed during probing: ${error}` });
  }

  const withState = result.snapshots.filter((snapshot) => snapshot.published !== null);
  if (result.snapshots.length > 0 && withState.length === 0) {
    issues.push({
      code: 'no-observation',
      message:
        'The widget never published an observation state, so its behaviour cannot be checked. Publish state after initialization and after every control change.',
    });
  }

  for (const snapshot of withState) {
    const bad = finiteNumbers(snapshot.published).filter((value) => !Number.isFinite(value));
    if (bad.length > 0) {
      issues.push({
        code: 'non-finite-state',
        message: `Probe "${snapshot.label}" published non-finite numeric values (${bad.join(', ')}).`,
      });
      break;
    }
  }

  const defaultSnapshot = result.snapshots.find((snapshot) => snapshot.label === 'default');
  for (const variable of claims.variables) {
    const low = result.snapshots.find((snapshot) => snapshot.label === `var:${variable.name}=min`);
    const high = result.snapshots.find((snapshot) => snapshot.label === `var:${variable.name}=max`);
    if (!low || !high) continue;
    if (observableSignature(low) === observableSignature(high)) {
      issues.push({
        code: 'dead-control',
        message: `Control "${variable.name}" has no observable effect: its minimum and maximum produce identical published state and visible text.`,
      });
    }
  }

  // The outline is the authority: a control it promised must exist. This is
  // the acceptance-criteria half of the contract — the prompt asks for it, and
  // this check enforces it against the generated config.
  for (const expected of claims.expectedVariables) {
    if (!outlineVariableCovered(expected, claims.variables)) {
      issues.push({
        code: 'outline-variable-missing',
        message: `The outline promised a control for "${expected}", but no generated variable corresponds to it.`,
      });
    }
  }

  if (defaultSnapshot) {
    const defaultSignature = observableSignature(defaultSnapshot);
    for (const preset of claims.presets) {
      const snapshot = result.snapshots.find(
        (candidate) => candidate.label === `preset:${preset.name}`,
      );
      if (!snapshot) continue;
      if (observableSignature(snapshot) === defaultSignature) {
        issues.push({
          code: 'inert-preset',
          message: `Preset "${preset.name}" leaves the widget in exactly the default state; it demonstrates nothing.`,
        });
      }
    }
  }

  return issues.slice(0, MAX_ISSUES);
}

function toObservations(snapshots: readonly WidgetProbeSnapshot[]): WidgetObservation[] {
  return snapshots.map((snapshot) => ({
    label: snapshot.label,
    values: snapshot.values,
    published: snapshot.published,
    visibleText: snapshot.visibleText,
  }));
}

/** Read declared sliders/presets from the embedded widget config. */
export function widgetClaims(
  config: Record<string, unknown> | undefined,
  expectedVariables: readonly string[] = [],
  expectedConcept?: string,
): WidgetVerificationContext['claims'] {
  const claims: WidgetVerificationContext['claims'] = {
    variables: [],
    presets: [],
    expectedVariables: [...expectedVariables],
    ...(expectedConcept ? { expectedConcept } : {}),
  };
  if (!config) return claims;

  const variables: WidgetVariableClaim[] = [];
  const rawVariables = Array.isArray(config.variables) ? config.variables : [];
  for (const raw of rawVariables) {
    if (!raw || typeof raw !== 'object') continue;
    const entry = raw as Record<string, unknown>;
    const name = typeof entry.name === 'string' ? entry.name.trim() : '';
    const min = typeof entry.min === 'number' ? entry.min : Number.NaN;
    const max = typeof entry.max === 'number' ? entry.max : Number.NaN;
    if (!name || !Number.isFinite(min) || !Number.isFinite(max) || max <= min) continue;
    const fallback = typeof entry.default === 'number' ? entry.default : min;
    const defaultValue = Math.min(max, Math.max(min, fallback));
    variables.push({ name, min, max, default: defaultValue });
  }

  const presets: WidgetPresetClaim[] = [];
  const rawPresets = Array.isArray(config.presets) ? config.presets : [];
  for (const raw of rawPresets) {
    if (!raw || typeof raw !== 'object') continue;
    const entry = raw as Record<string, unknown>;
    const name = typeof entry.name === 'string' ? entry.name.trim() : '';
    const values: Record<string, number> = {};
    if (entry.variables && typeof entry.variables === 'object') {
      for (const [key, value] of Object.entries(entry.variables as Record<string, unknown>)) {
        if (typeof value === 'number' && Number.isFinite(value)) values[key] = value;
      }
    }
    if (name && Object.keys(values).length > 0) presets.push({ name, variables: values });
  }

  claims.variables = variables;
  claims.presets = presets;
  return claims;
}

/** Build the blind verifier prompt. The HTML source is never included. */
export function buildBlindWidgetPrompt(context: WidgetVerificationContext): {
  system: string;
  user: string;
} {
  const system = [
    'You are an independent consistency checker for an educational simulation.',
    "You receive the simulation's own claims and a table of OBSERVED behaviour from probe runs.",
    'You do NOT receive its source code. Judge only what the observations show.',
    'The outline is the authority: claims.expectedVariables and claims.expectedConcept describe what was promised; treat a missing or renamed control as a real finding.',
    'Report concrete contradictions between the claims and the observed behaviour, for example:',
    '- a preset named after an effect that never appears in the published state or visible text;',
    '- a quantity whose published values can never reach a state the description promises;',
    '- a unit label attached to a value with no plausible relation to the declared inputs;',
    '- visible text or a status badge that contradicts the published number.',
    'Do not speculate and do not suggest code. If the observations are consistent, return [].',
    'Reply with ONLY a JSON array of objects: [{"code":"claim-mismatch","message":"..."}].',
    `Return at most ${MAX_ISSUES} issues; each message at most ${MAX_MESSAGE_CHARS} characters.`,
  ].join('\n');

  const user = JSON.stringify(
    {
      widgetType: context.widgetType,
      title: context.title,
      description: context.description,
      keyPoints: context.keyPoints,
      claims: context.claims,
      scriptErrors: context.scriptErrors,
      observations: toObservations(context.observations),
    },
    null,
    2,
  );
  return { system, user };
}

function normalizeIssues(parsed: unknown): WidgetVerificationIssue[] {
  if (!Array.isArray(parsed)) return [];
  const issues: WidgetVerificationIssue[] = [];
  for (const entry of parsed) {
    if (!entry || typeof entry !== 'object') continue;
    const record = entry as Record<string, unknown>;
    const code = typeof record.code === 'string' ? record.code.trim() : '';
    const message = typeof record.message === 'string' ? record.message.trim() : '';
    if (!code || !message) continue;
    issues.push({ code: code.slice(0, 60), message: message.slice(0, MAX_MESSAGE_CHARS) });
    if (issues.length >= MAX_ISSUES) break;
  }
  return issues;
}

/**
 * Blind verifier backed by the generation call itself. A fresh call with a
 * different system prompt and no source is a genuinely independent read even
 * when it is the same model — and, unlike quiz verification, this needs no
 * operator route to exist, so it also runs in server-side classroom jobs.
 */
export function createAiWidgetVerifier(aiCall: AICallFn): WidgetVerifier {
  return async (context) => {
    const { system, user } = buildBlindWidgetPrompt(context);
    const raw = await aiCall(system, user);
    const parsed = parseJsonResponse<unknown>(raw);
    return normalizeIssues(parsed);
  };
}

/** Fail-open wrapper shared by host-provided and built-in verifiers. */
export async function verifyWidgetSafely(
  verifier: WidgetVerifier | undefined,
  context: WidgetVerificationContext,
  log?: { warn: (message: string) => void },
): Promise<WidgetVerificationIssue[]> {
  if (!verifier) return [];
  try {
    const verdict = await verifier(context);
    return verdict ? normalizeIssues(verdict) : [];
  } catch (error) {
    log?.warn(
      `Widget claim verifier failed for "${context.title}"; keeping generated content: ${String(error)}`,
    );
    return [];
  }
}

/** Compact, model-facing feedback for a corrective re-prompt. */
export function summarizeWidgetIssues(issues: readonly WidgetVerificationIssue[]): string {
  const lines = issues.map((issue) => `- [${issue.code}] ${issue.message}`);
  return [
    'Your previous simulation contradicted its own claims. Correct it and reply with the complete HTML document:',
    ...lines,
    'The published state, visible labels and presets must all agree with one model of the system.',
  ].join('\n');
}

/**
 * Probe once, run the mechanical checks, then consult the blind verifier only
 * if the mechanical pass was clean. That ordering keeps deterministic checks
 * first and avoids paying for a model call when the artifact is already broken.
 */
export async function verifyWidgetArtifact(
  html: string,
  shape: Omit<WidgetVerificationContext, 'observations' | 'scriptErrors'>,
  verifier: WidgetVerifier | undefined,
  log?: { warn: (message: string) => void },
): Promise<{
  issues: WidgetVerificationIssue[];
  context: WidgetVerificationContext;
}> {
  const result: WidgetProbeResult = probeWidgetHtml(html, {
    variables: shape.claims.variables.map((variable) => ({ ...variable })),
    presets: shape.claims.presets.map((preset) => ({
      ...preset,
      variables: { ...preset.variables },
    })),
  });
  const context: WidgetVerificationContext = {
    ...shape,
    observations: toObservations(result.snapshots),
    scriptErrors: result.errors,
  };
  let issues = deterministicWidgetIssues(result, shape.claims);
  if (issues.length === 0 && verifier) {
    issues = await verifyWidgetSafely(verifier, context, log);
  }
  return { issues, context };
}
